Definition w4s_B3_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 : word)
         (P SS n SBL SBH S3 l : Z),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (S3 + l - 1) 1 1 [(0, 1, 255)] ->
    SS + 6 <= S3 -> 8 <= l < 65536 -> S3 + l <= SS + n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (a4 a5 a6 a7 : word), 1 <= r <= 255 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 (Z_to_bv 64 (S3 + l + -1))
                                 (Z_to_bv 64 (S3 + l)) (Z_to_bv 64 r) x13 a4 a5 a6 a7 x18 x19 x20 x21 x30 x23
                                 (Z_to_bv 64 (S3 + l + -8)) x25 x26 x27 x28 x29 x30 (Z_to_bv 64 l))
                            F (Z_to_bv 64 0x9091c) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 (Z_to_bv 64 l))
                        F (Z_to_bv 64 0x908c0) fc None mm (seg_rom asegs)).

