         (x1 gp tp x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 : word)
         (P SS n SBL SBH S3 l lo hi : Z) (w216 : word),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (S3 + l - 1) 1 1 [(0, lo, hi)] -> (lo = 1 /\ hi = 255 \/ lo = 0 /\ hi = 0) ->
    SS + 6 <= S3 -> 1 <= l <= 7 -> S3 + l <= SS + n ->
    rw_cells asegs mm (P + 216) [C8 w216] -> rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (a2 a4 a5 a6 c : word) (mm' : amem), 1 <= r <= 255 -> lo = 1 ->
       munch [(P + 216, P + 224)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> rw_cells asegs mm' (P + 216) [C8 c] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 (Z_to_bv 64 r) (Z_to_bv 64 (S3 + l)) a2 x13
                                 a4 a5 a6 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 (Z_to_bv 64 l))
                            F (Z_to_bv 64 0x90b88) fc None mm' (seg_rom asegs))) ->
    (forall (a0 a2 a4 a5 a6 c : word) (mm' : amem), lo = 0 ->
       munch [(P + 216, P + 224)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> rw_cells asegs mm' (P + 216) [C8 c] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 a0 (Z_to_bv 64 (S3 + l)) a2 x13
                                 a4 a5 a6 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 (Z_to_bv 64 l))
                            F (Z_to_bv 64 0x91bc0) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 (Z_to_bv 64 l))
                        F (Z_to_bv 64 0x908c0) fc None mm (seg_rom asegs)).

Ltac w4s_small3_post K K0 C216 P S3 l :=
  kx_post_regs_keep;
  lazymatch goal with H : log_flat ?E' ?log |- _ => rename H into HLF end;
  let MU := fresh "MU" in let WM := fresh "WM" in
  lazymatch goal with |- context [MS _ _ _ _ _ (mem_denot _ ?m _) _] =>
    pose proof (munch_refl [(P + 216, P + 224)] m) as MU; pose proof (wmono_refl asegs m) as WM end;
  kx_munch_wins MU [(P + 216, 8)];
  kx_post_mem_free;
  kx_cell C216;
  try replace (l + S3) with (S3 + l) by apply Z.add_comm;
  lazymatch goal with
  | |- evtF _ _ _ (MS _ _ (Z_to_bv 64 0x91bf0) _ _ _ _) => eapply K0; [ reflexivity | exact MU | exact WM | eassumption | exact C216 ]
  | |- evtF _ _ _ (MS (mkR _ _ _ _ _ _ _ _ _ (ev ?E' ?j) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
      let H := fresh "H" in kx_range (EVar j) H;
      replace (ev E' j) with (Z_to_bv 64 (bv_unsigned (ev E' j))) by (apply Z_to_bv_bv_unsigned);
      eapply (K (bv_unsigned (ev E' j))); [ exact H | reflexivity | exact MU | exact WM | eassumption | exact C216 ]
  end.

